func runAuthStatus(ctx context.Context, w io.Writer, fetchProfile profileFetcher, listSessions authSessionLister, t statusTarget) error {
	if t.token == "" {
		fmt.Fprintf(w, "Not logged in to %s\n", t.coreURL)
